// RD-RACEOPS-01 Sprint 2 · Result import — every tunable, in ONE place.
//
// "No hardcoded values": nothing below may be repeated inline anywhere in the module.
//
// Why results get their own caps rather than reusing IMPORT_MAX_ROWS (2,000) /
// IMPORT_MAX_FILE_BYTES (5 MB) from lib/registrations/importTemplate.ts: those bound a
// MANUAL participant-entry template, where 2,000 is a sane human limit. A results file
// is machine-generated by a timing provider — a large city marathon legitimately
// exceeds 20,000 finishers in one race. Reusing the registration caps would reject
// valid files. These constants are deliberately separate and separately justified.

/** Upper bound on data rows in one results file. */
export const RESULTS_MAX_ROWS = 50_000

/** Upper bound on uploaded file size. */
export const RESULTS_MAX_FILE_BYTES = 15 * 1024 * 1024   // 15 MB

/**
 * Extensions accepted. ZIP remains explicitly future-only.
 *
 * RD-RACEOPS-RESULTS-06 · `.pdf` means a TEXT pdf — one whose words can be selected in a
 * reader. A scanned or photographed results sheet carries no text to extract and is
 * refused with a message that says so; OCR is not supported and is not implied anywhere in
 * the UI (see `PDF_SUPPORT_NOTE`).
 */
export const RESULTS_ACCEPTED_EXTENSIONS = ['.csv', '.xlsx', '.pdf'] as const

/**
 * The accepted extensions as a sentence: ".csv, .xlsx or .pdf".
 *
 * RD-RACEOPS-RESULTS-06 · a plain `join(' or ')` read ".csv or .xlsx or .pdf" the moment a
 * third format arrived. Derived here so every message reads the same and adding a fourth
 * format changes no copy.
 */
export function formatAcceptedExtensions(): string {
  const list = [...RESULTS_ACCEPTED_EXTENSIONS]
  if (list.length <= 1) return list[0] ?? ''
  return `${list.slice(0, -1).join(', ')} or ${list[list.length - 1]}`
}

/** The single sentence every surface uses to describe PDF support. One wording, one claim. */
export const PDF_SUPPORT_NOTE =
  'Text-based PDFs from your timing provider are supported. Scanned or photographed results cannot be read.'

/** `accept` attribute for the file input — derived, never written out by hand. */
export const RESULTS_FILE_ACCEPT = RESULTS_ACCEPTED_EXTENSIONS.join(',')

/** Rows rendered in the preview table before paging. The full validated set stays in
 *  memory; this only bounds what is painted, so a 50k-row file cannot stall the tab. */
export const RESULTS_PREVIEW_PAGE_SIZE = 50

/** Rows shown in the on-screen issue list. The downloadable CSV report is never
 *  truncated — see buildValidationReportCsv. */
export const RESULTS_ISSUE_PREVIEW_LIMIT = 200

/** Filename stem for the downloadable validation report. */
export const VALIDATION_REPORT_FILENAME_STEM = 'validation-report'

export function formatMaxFileSize(): string {
  return `${Math.round(RESULTS_MAX_FILE_BYTES / (1024 * 1024))} MB`
}
